#!/usr/bin/env bash
# Generated by pipeline_compiler. nvinfer_backport must be on the GStreamer
# plugin path (verify: gst-inspect-1.0 nvinfer_backport). Override CAM /
# CAM_W / CAM_H / CAM_FPS / CAM_FMT via env to match your camera's
# supported capture modes (`v4l2-ctl --list-formats-ext -d <device>`).
set -euo pipefail
DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

CAM="${CAM:-/dev/video0}"
CAM_W=${CAM_W:-1920}
CAM_H=${CAM_H:-1080}
CAM_FPS=${CAM_FPS:-30}
CAM_FMT="${CAM_FMT:-YUYV}"

# ── Metadata sink config ──────────────────────────────────────────
# Read by the nvcustomprocess user libraries in build/ (the element
# has no config-file property). Override any of these at run time:
#   MQTT_HOST=10.0.0.9 ./run.sh      JSON_OUT=/tmp/d.json ./run.sh
export JSON_OUT="${JSON_OUT:-/home/atharv/spectra/output/events.json}"
export JSON_MIN_CONF="${JSON_MIN_CONF:-0.0}"
export JSON_MASK_OUTLINE="${JSON_MASK_OUTLINE:-0}"
mkdir -p "$(dirname "${JSON_OUT}")" 2>/dev/null || true
echo "[run.sh] JSON -> ${JSON_OUT}" >&2

# ── Recording output dirs ─────────────────────────────────────────
# A missing directory here is a hard failure at pipeline start (the
# sink element does not create one for you); mkdir -p up front so a
# fresh project layout never needs a manual mkdir.
mkdir -p "$(dirname "/home/atharv/spectra/output/frames/frame.jpg")" 2>/dev/null || true

if [ -f "${DIR}/parsers/Makefile" ] && command -v make >/dev/null 2>&1; then
  make -C "${DIR}/parsers" || { echo "parser/.so build failed" >&2; exit 1; }
fi

gst-launch-1.0 -e nvstreammux name=mux batch-size=1 width=778 height=520 batched-push-timeout=40000 live-source=0 nvurisrcbin uri="file:///home/atharv/spectra/input/kitchen-sample.mp4" ! mux.sink_0 mux. ! queue max-size-buffers=4 ! nvvideoconvert ! queue max-size-buffers=4 ! nvinfer_backport config-file-path="${DIR}/configs/config_vggt.txt" ! queue max-size-buffers=4 ! nvcustomprocess custom-lib-path="${DIR}/build/libvggt_render_process.so" process-func-name=NvDsCustomPostProcess ! queue max-size-buffers=4 ! nvcustomprocess custom-lib-path="${DIR}/build/libmeta_json.so" process-func-name=MetaJson ! queue max-size-buffers=4 ! nvvideoconvert ! "video/x-raw,format=I420" ! jpegenc ! multifilesink location="/home/atharv/spectra/output/frames/frame.jpg"
